<script setup lang="ts">
import {ref,onMounted} from 'vue';import AdminDialog from './AdminDialog.vue';const props=defineProps<{csrf?:string}>();const emit=defineEmits(['changed']);const rows=ref<any[]>([]),editor=ref<any>(null),error=ref(''),busy=ref(false);
async function request(path='',method='GET',body?:any){const r=await fetch('/pms/api/permissions'+path,{method,headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':props.csrf||''},body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok)throw Error(d.errors?Object.values(d.errors).flat().join(' '):d.message);return d;}
async function load(){try{rows.value=(await request()).data;}catch(e){error.value=(e as Error).message;}}
async function save(){busy.value=true;error.value='';try{await request(editor.value.id?'/'+editor.value.id:'','POST',editor.value);editor.value=null;await load();emit('changed');}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function remove(row:any){if(!confirm('Delete permission '+row.permission_name+' from every PMS role?'))return;busy.value=true;error.value='';try{await request('/'+row.id,'DELETE');await load();emit('changed');}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
onMounted(load);
</script><template><div class="admin-section-heading"><h3>PMS permission catalogue</h3><button class="button" @click="editor={permission_name:'',permission_key:''}">Create permission</button></div><p class="muted">Existing permission keys remain fixed when renaming. A new key only controls functionality that implements that permission.</p><p v-if="error" class="notice admin-error">{{error}}</p><AdminDialog v-if="editor" :title="editor.id?'Edit permission':'Create permission'" :busy="busy" @close="editor=null"><form class="admin-editor" @submit.prevent="save"><label>Permission name<input v-model="editor.permission_name" required maxlength="255"></label><label>Permission key<input v-model="editor.permission_key" required :readonly="!!editor.id" maxlength="255"></label><p v-if="error" class="notice admin-error" role="alert">{{error}}</p><div class="editor-actions"><button class="button primary" :disabled="busy">Save permission</button><button type="button" class="button" @click="editor=null">Cancel</button></div></form></AdminDialog><div class="admin-list"><article v-for="row in rows" :key="row.id"><div><strong>{{row.permission_name}}</strong><small class="muted"> {{row.permission_key}}</small></div><div class="row-actions"><button @click="editor={...row}">Edit</button><button :disabled="busy" @click="remove(row)">Delete</button></div></article></div></template>
